df_nmiav4 <- read_feather(paste0(data_path, "openml_cc18_syn_noisy_miav_0.2_additional.feather"))
df_nmiav5 <- read_feather(paste0(data_path, "openml_cc18_syn_noisy_miav_0.25_additional.feather"))
df_nmiav6 <- read_feather(paste0(data_path, "openml_cc18_syn_noisy_miav_0.3_additional.feather"))

## evaluate the noise-MIAV datasets w.r.t the fidelity and privacy metrics

set.seed(12345)
out_nmiav1 <- EvaluateSyntheticData(df_split = df_split,
