                                   n_runs = 5)
save(out_nmiav3, file = "real_data_evaluations_15_additional_datasets_noisy_miav_0.15.RData", compress = TRUE)


set.seed(12345)
out_nmiav4 <- EvaluateSyntheticData(df_split = df_split,
                                   df_synth = df_nmiav4,
                                   n_runs = 5)
save(out_nmiav4, file = "real_data_evaluations_15_additional_datasets_noisy_miav_0.2.RData", compress = TRUE)


set.seed(12345)
out_nmiav5 <- EvaluateSyntheticData(df_split = df_split,
